<?php
require __DIR__.'/../../config/bootstrap.php';
use Pharmacy\Auth\Authorization;use Pharmacy\Suppliers\SupplierRepository;use Pharmacy\Support\Csrf;
Authorization::requireRole('ADMIN','INVENTORY');$repo=new SupplierRepository($pdo);$message=$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){try{Csrf::validate((string)($_POST['csrf']??''));$repo->save(['supplier_code'=>trim($_POST['supplier_code']??''),'name'=>trim($_POST['name']??''),'address'=>trim($_POST['address']??''),'phone'=>trim($_POST['phone']??''),'email'=>trim($_POST['email']??''),'gst_no'=>trim($_POST['gst_no']??''),'contact_person'=>trim($_POST['contact_person']??''),'active'=>1]);$message='Supplier saved.';}catch(Throwable $e){$error=$e->getMessage();}}
$rows=$repo->active();$title='Suppliers';require __DIR__.'/../../templates/header.php';?>
<h2 class="page-title">Suppliers</h2><?php if($message):?><div data-flash="<?=htmlspecialchars($message)?>"></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?>
<div class="row g-3"><div class="col-lg-4"><div class="card"><div class="card-body"><h5>Add Supplier</h5><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars(Csrf::token())?>"><?php foreach(['supplier_code'=>'Supplier Code','name'=>'Supplier Name','contact_person'=>'Contact Person','phone'=>'Phone','email'=>'Email','gst_no'=>'GST No.','address'=>'Address'] as $n=>$l):?><div class="mb-2"><label class="form-label"><?=$l?></label><input class="form-control" name="<?=$n?>" <?=$n==='supplier_code'||$n==='name'?'required':''?>></div><?php endforeach;?><button class="btn btn-dark">Save</button></form></div></div></div><div class="col-lg-8"><div class="card"><div class="card-body"><table class="table datatable"><thead><tr><th>Code</th><th>Name</th><th>Contact</th><th>Phone</th><th>GST</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['supplier_code'])?></td><td><?=htmlspecialchars($r['name'])?></td><td><?=htmlspecialchars($r['contact_person']??'')?></td><td><?=htmlspecialchars($r['phone']??'')?></td><td><?=htmlspecialchars($r['gst_no']??'')?></td></tr><?php endforeach;?></tbody></table></div></div></div></div><?php require __DIR__.'/../../templates/footer.php';
